using System;using System.Linq;using System.Threading;using System.Diagnostics;namespace ServiceTool{internal static class PaymentLiveTests{[STAThread]static int Main(){try{string root=@"C:\DataKrat\Bars.PaymentProcessing.Service.0.14.1.win-x64";var process=Process.GetProcessesByName("Bars.PaymentProcessing.Service").FirstOrDefault(p=>{try{return p.MainModule.FileName.StartsWith(root,StringComparison.OrdinalIgnoreCase);}catch{return false;}});if(process==null)throw new Exception("Specified Payment process not running");var ports=ServiceEndpoints.Listeners((uint)process.Id);Console.WriteLine("Payment PID="+process.Id+" listeners="+ports.Count);var addresses=ServiceHostingConfig.Read(System.IO.Path.Combine(root,"Bars.PaymentProcessing.Service.exe")).Where(u=>ports.Any(p=>p.Port==new Uri(u).Port)).ToList();string swagger=ServiceSwagger.Find(addresses,CancellationToken.None);if(swagger==null||new Uri(swagger).AbsolutePath!="/index.html")throw new Exception("Root Swagger not detected");Console.WriteLine("PASS real Payment confirmed by PID/configuration: "+swagger);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}